import{_ as s,c as t,o as n,j as r,Y as i,t as o}from"./chunks/framework.BNTND4LZ.js";const b=JSON.parse('{"title":"ip-sr | x-cmd man (ip man8) | IPv6 Segment Routing management","titleTemplate":false,"description":"x-cmd man (ip man8 Manual Page) | ip-sr - IPv6 Segment Routing management","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ip-sr | x-cmd man (ip man8) | IPv6 Segment Routing management"}],["meta",{"name":"og:description","content":"x-cmd man (ip man8 Manual Page) | ip-sr - IPv6 Segment Routing management"}]]},"headers":[],"params":{"isMan":true,"man":"ip-sr","category":"ip man8","desc":"IPv6 Segment Routing management"},"relativePath":"ip/man8/ip-sr.md","filePath":"ip/man8/[man].md"}'),p={name:"ip/man8/ip-sr.md"},h={class:"visually-hidden"};function d(a,e,m,l,c,g){return n(),t("div",null,[r("h1",h,o(a.$params.man),1),e[0]||(e[0]=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ip-sr - IPv6 Segment Routing management</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ip sr</strong> { <em>COMMAND</em> | <strong>help</strong> }</p><p><strong>ip sr hmac show</strong></p><p><strong>ip sr hmac set</strong> <em>KEYID ALGO</em></p><p><strong>ip sr tunsrc show</strong></p><p><strong>ip sr tunsrc set</strong> <em>ADDRESS</em></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>ip sr</strong> command is used to configure IPv6 Segment Routing (SRv6) internal parameters.</p><p>Those parameters include the mapping between an HMAC key ID and its associated hashing algorithm and secret, and the IPv6 address to use as source for encapsulated packets.</p><p>The <strong>ip sr hmac set</strong> command prompts for a passphrase that will be used as the HMAC secret for the corresponding key ID. A blank passphrase removes the mapping. The currently supported algorithms for <em>ALGO</em> are <strong>sha1</strong> and <strong>sha256</strong>.</p><p>If the tunnel source is set to the address :: (which is the default), then an address of the egress interface will be selected. As this operation may hinder performances, it is recommended to set a non-default address.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><h3 id="configure-an-hmac-mapping-for-key-id-42-and-hashing-algorithm-sha-256" tabindex="-1">Configure an HMAC mapping for key ID 42 and hashing algorithm SHA-256 <a class="header-anchor" href="#configure-an-hmac-mapping-for-key-id-42-and-hashing-algorithm-sha-256" aria-label="Permalink to &quot;Configure an HMAC mapping for key ID 42 and hashing algorithm SHA-256&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip sr hmac set 42 sha256</span></span></code></pre></div><h3 id="set-the-tunnel-source-address-to-2001-db8-1" tabindex="-1">Set the tunnel source address to 2001:db8::1 <a class="header-anchor" href="#set-the-tunnel-source-address-to-2001-db8-1" aria-label="Permalink to &quot;Set the tunnel source address to 2001:db8::1&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip sr tunsrc set 2001:db8::1</span></span></code></pre></div><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><br> <strong>ip-route</strong>(8)</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>David Lebrun &lt;david.lebrun@uclouvain.be&gt;</p>',22))])}const f=s(p,[["render",d]]);export{b as __pageData,f as default};
